let fed = false;  
// ... 수천억개 변수  
function wakeUp() { console.log("wakeup"); mood = "Cry"; }  
function checkDiaper() { if (!diaperClean) { console.log("diaper"); diaperClean = true; } }  
function feed() { console.log("feeding"); hunger = 10; fed = true; }  
// ... 모든 함수가 전역 변수에 직접 접근  
// Main  
wakeUp();  
checkDiaper();  
feed();  
// ...  
**vs**  
class Baby {  
constructor(name) {  
this.name = name;  
this.hunger = 80;  
this.isDiaperClean = false;  
this.mood = "Neutral";  
}  
wakeUp() {  
console.log(`${this.name}일어남`);  
this.mood = "Cry";  
}  
feed() {  
console.log(`${this.name}분유 먹음.`);  
this.hunger = 10;  
this.mood = "Happy";  
}  
changeDiaper() {  
this.isDiaperClean = true;  
console.log("기저귀 갈아줌.");  
}  
}  
// Main  
const myBaby = new Baby("x");  
myBaby.wakeUp();  
myBaby.feed();  
1) 남자가 개입해도 되는  
여지를 정확하게 제공하고,  
도움받을 수 있는 것과  
도움받을 수 없는 것을  
**잘 구분해야** 써먹을 수 있음  
**\* 뭐가 더 좋고, 나쁘다 (x)**  
**목적, 쓰임에 따라 다르다 (o)**  
